#!/usr/bin/env python3
"""Scriptable fake age plugin. Behaviour driven by env:
   PLUGIN_LOG   - log file (append)
   PLUGIN_SCRIPT- python file exec'd with helpers in scope; if absent uses default
   PLUGIN_TIMEOUT
"""
import os, sys, base64, time

LOG = os.environ.get("PLUGIN_LOG", "/tmp/w/plug/log/last.log")
lf = open(LOG, "a", buffering=1)
def L(s):
    lf.write(s + "\n")

def b64(b):
    return base64.b64encode(b).decode().rstrip("=")
def ub64(s):
    return base64.b64decode(s + "=" * (-len(s) % 4))

L("=== INVOCATION pid=%d t=%.3f ===" % (os.getpid(), time.time()))
L("ARGV: %r" % (sys.argv,))
for k in sorted(os.environ):
    if k.startswith("AGE"):
        L("ENV %s=%r" % (k, os.environ[k]))

IN = sys.stdin.buffer
OUT = sys.stdout.buffer

def readline():
    ln = IN.readline()
    if not ln:
        L("RECV <EOF>")
        raise EOFError
    ln = ln.rstrip(b"\n")
    L("RECV %r" % (ln.decode("utf-8", "replace"),))
    return ln.decode("utf-8", "replace")

def read_stanza():
    """Returns (args_list, body_bytes)."""
    ln = readline()
    while ln == "":
        ln = readline()
    assert ln.startswith("-> "), "bad stanza start %r" % ln
    args = ln[3:].split(" ")
    b64lines = []
    while True:
        l = readline()
        b64lines.append(l)
        if len(l) < 64:
            break
    return args, ub64("".join(b64lines))

def send(args, body=b""):
    s = "-> " + " ".join(args) + "\n"
    enc = b64(body)
    if enc == "":
        s += "\n"
    else:
        i = 0
        while True:
            chunk = enc[i:i+64]
            s += chunk + "\n"
            i += 64
            if len(chunk) < 64:
                break
    L("SEND %r" % s)
    OUT.write(s.encode())
    OUT.flush()

g = dict(globals())
scr = os.environ.get("PLUGIN_SCRIPT")
if scr:
    code = open(scr).read()
else:
    code = "collect_and_exit()"

def collect_and_exit():
    try:
        while True:
            a, b = read_stanza()
            L("  STANZA args=%r body=%r" % (a, b))
    except EOFError:
        pass

g["collect_and_exit"] = collect_and_exit
try:
    exec(code, g)
except SystemExit:
    raise
except EOFError:
    L("!!! EOFError in script")
except BaseException as e:
    L("!!! EXC %r" % (e,))
    sys.exit(9)
L("=== plugin exiting 0 ===")
sys.exit(0)
